from typing import List

def parse_music(music_string: str) -> List[int]:
    music_map = {'o': 4, 'o|': 2, '.|': 1}
    notes = music_string.split()

    beats = []
    i = 0
    while i < len(notes):
        if notes[i] in music_map:
            beats.append(music_map[notes[i]])
            i += 1
        elif i+1 < len(notes) and (notes[i] + notes[i+1]) in music_map:
            beats.append(music_map[notes[i] + notes[i+1]])
            i += 2
        else:
            i += 1
    return beats
